import React, { useState, useEffect } from "react";
import api from "../../api";
import { FaPlus } from "react-icons/fa";
import 'animate.css';

const Artikel = () => {
  const [data, setData] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    judul: "",
    categori: "",
    content: "",
    gambar: null
  });

  useEffect(() => {
    api.get('/artikel')
      .then(response => {
        setData(response.data);
      })
      .catch(error => {
        console.error("Error fetching data:", error);
      });
  }, []);

  const handleOpenModal = () => {
    setShowModal(true);
    setFormData({
      judul: "",
      categori: "",
      content: "",
      gambar: null
    });
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setFormData(prev => ({ ...prev, gambar: file }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const formDataToSend = new FormData();
    formDataToSend.append('judul', formData.judul);
    formDataToSend.append('categori', formData.categori);
    formDataToSend.append('content', formData.content);
    if (formData.gambar) formDataToSend.append('gambar', formData.gambar);

    api.post('/artikel', formDataToSend)
      .then(response => {
        setData([...data, response.data]);
        setShowModal(false);
      })
      .catch(error => {
        console.error("Error submitting form:", error);
      });
  };

  return (
    <div>
      {/* Button Create Artikel */}
      <button
        onClick={handleOpenModal}
        className="bg-teal-500 text-white py-2 px-4 rounded-lg mb-4 flex items-center"
      >
        <FaPlus className="inline-block mr-2 mb-1" /> Create Artikel
      </button>

      <div className="grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Judul</th>
              <th className="px-6 py-3 text-left font-medium">Kategori</th>
              <th className="px-6 py-3 text-left font-medium">Content</th>
              <th className="px-6 py-3 text-left font-medium">Action</th>
            </tr>
          </thead>
          <tbody>
            {data.length > 0 ? (
              data.map((row, index) => (
                <tr key={row.id}>
                  <td className="px-6 py-4">{index + 1}</td>
                  <td className="px-6 py-4">{row.judul}</td>
                  <td className="px-6 py-4">{row.categori}</td>
                  <td className="px-6 py-4">{row.content}</td>
                  <td className="px-6 py-4">
                    <button
                      onClick={handleOpenModal}
                      className="bg-teal-500 text-white py-1 px-3 rounded-lg"
                    >
                      Edit
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" className="text-center px-6 py-4 text-gray-500">
                  Tidak ada jadwal tersedia.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Modal Form */}
      {showModal && (
        <div className="fixed inset-0 bg-gray-500 bg-opacity-50 flex justify-center items-center z-50 animate__animated animate__fadeIn animate__faster">
          <div className="bg-white p-8 rounded-lg shadow-xl w-full max-w-lg animate__animated animate__zoomIn animate__faster">
            <h2 className="text-2xl font-semibold text-teal-700 mb-6 text-center">Tambah Artikel</h2>
            <form onSubmit={handleSubmit}>
              <div className="mb-6">
                <label htmlFor="judul" className="block text-sm font-medium text-gray-700 mb-2">
                  Judul
                </label>
                <input
                  type="text"
                  id="judul"
                  name="judul"
                  value={formData.judul}
                  onChange={handleInputChange}
                  className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                  placeholder="Masukkan judul artikel"
                />
              </div>
              
              <div className="mb-6">
                <label htmlFor="categori" className="block text-sm font-medium text-gray-700 mb-2">
                  Kategori
                </label>
                <input
                  type="text"
                  id="categori"
                  name="categori"
                  value={formData.categori}
                  onChange={handleInputChange}
                  className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                  placeholder="Masukkan kategori artikel"
                />
              </div>
              
              <div className="mb-6">
                <label htmlFor="content" className="block text-sm font-medium text-gray-700 mb-2">
                  Content
                </label>
                <textarea
                  id="content"
                  name="content"
                  value={formData.content}
                  onChange={handleInputChange}
                  className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                  rows="5"
                  placeholder="Masukkan isi artikel"
                />
              </div>
      
              <div className="mb-6">
                <label htmlFor="gambar" className="block text-sm font-medium text-gray-700 mb-2">
                  Gambar
                </label>
                <input
                  type="file"
                  id="gambar"
                  name="gambar"
                  onChange={handleFileChange}
                  className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                />
              </div>
      
              <div className="flex justify-end gap-4">
                <button
                  type="button"
                  onClick={handleCloseModal}
                  className="bg-gray-300 text-gray-800 py-2 px-6 rounded-lg font-semibold hover:bg-gray-400 transition duration-200"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="bg-teal-600 text-white py-2 px-6 rounded-lg font-semibold hover:bg-teal-700 transition duration-200"
                >
                  Submit
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
};

export default Artikel;
